from dataclasses import dataclass

import pytest


@dataclass
class BeforeBirth(Exception):
    born: int
    now: int


def age_at(born: int, now: int) -> int:
    """Whole years between birth year `born` and current year `now`.

    Only years are compared, so the result is now - born. The clock is
    never read. Raises BeforeBirth if now < born.
    """
    if now < born:
        raise BeforeBirth(born, now)
    return now - born


def test_typical_age() -> None:
    assert age_at(2000, 2025) == 25


def test_same_year_is_zero() -> None:
    assert age_at(2026, 2026) == 0


def test_one_year() -> None:
    assert age_at(1999, 2000) == 1


def test_long_lifespan() -> None:
    assert age_at(1900, 2026) == 126


def test_result_is_int() -> None:
    assert isinstance(age_at(1990, 2020), int)


def test_before_birth_raises() -> None:
    with pytest.raises(BeforeBirth):
        age_at(2026, 2025)


def test_before_birth_carries_values() -> None:
    with pytest.raises(BeforeBirth) as info:
        age_at(2030, 2020)
    assert info.value.born == 2030
    assert info.value.now == 2020

